(FAMILY BNDLIG)
(DESIGNSIZE R 10.0)
(DESIGNUNITS R 10.0)
(BOUNDARYCHAR C Z)
(FONTDIMEN
   (SLANT R 0.0)
   (SPACE R 3.0)
   (STRETCH R 1.0)
   (SHRINK R 1.0)
   (XHEIGHT R 4.0)
   (QUAD R 10.0)
   )
(LIGTABLE
   (LABEL BOUNDARYCHAR)
   (/LIG/ C a C x)
   (/LIG C b C y)
   (LIG/ C c C x)
   (LIG C d C y)
   (STOP)
   (LABEL C a)
   (/LIG/> C b C c)
   (LIG/> C c C x)
   (KRN C Z R 5.0)
   (STOP)
   (LABEL C b)
   (/LIG> C a C d)
   (/LIG C Z C x)
   (STOP)
   (LABEL C c)
   (KRN C b R 1.0)
   (/LIG/>> C a C y)
   (STOP)
   (LABEL C d)
   (/LIG/ C d C x)
   (STOP)
   (LABEL C x)
   (KRN C c R 2.0)
   (STOP)
   (LABEL C y)
   (KRN C a R 3.0)
   (STOP)
   )
(CHARACTER C a (CHARWD R 1.0) (CHARHT R 1.0))
(CHARACTER C b (CHARWD R 2.0) (CHARHT R 1.0))
(CHARACTER C c (CHARWD R 4.0) (CHARHT R 1.0))
(CHARACTER C d (CHARWD R 8.0) (CHARHT R 1.0))
(CHARACTER C x (CHARWD R 16.0) (CHARHT R 1.0))
(CHARACTER C y (CHARWD R 32.0) (CHARHT R 1.0))
